package com.ananttomar.aetherfall.client.model;

import com.ananttomar.aetherfall.AetherfallMod;
import com.ananttomar.aetherfall.entity.boss.AetherfallEntity;
import net.minecraft.util.Mth;
import software.bernie.geckolib.constant.DataTickets;
import software.bernie.geckolib.core.animatable.model.CoreGeoBone;
import software.bernie.geckolib.core.animation.AnimationState;
import software.bernie.geckolib.model.DefaultedEntityGeoModel;
import software.bernie.geckolib.model.data.EntityModelData;

/**
 * GeckoLib model for the World Eater. Resources (all generated by {@code tools/model/world_eater.py}):
 * <ul>
 *     <li>{@code geo/entity/world_eater.geo.json}</li>
 *     <li>{@code textures/entity/world_eater.png} (+ {@code world_eater_glow.png} for the emissive layer)</li>
 *     <li>{@code animations/entity/world_eater.animation.json}</li>
 * </ul>
 * Head look is spread along the neck (30% / 30% / 40%) so a giant creature turns its whole neck, not just its skull.
 */
public class AetherfallModel extends DefaultedEntityGeoModel<AetherfallEntity> {
    private static final float[] NECK_SHARE = {0.3F, 0.3F, 0.4F};
    private static final String[] NECK_BONES = {"neck_lower", "neck_upper", "head"};

    public AetherfallModel() {
        super(AetherfallMod.id("world_eater"), false);
    }

    @Override
    public void setCustomAnimations(AetherfallEntity animatable, long instanceId, AnimationState<AetherfallEntity> state) {
        super.setCustomAnimations(animatable, instanceId, state);
        if (animatable.isDeadOrDying()) {
            return;
        }
        EntityModelData data = state.getData(DataTickets.ENTITY_MODEL_DATA);
        if (data == null) {
            return;
        }
        float yaw = Mth.clamp(data.netHeadYaw(), -60.0F, 60.0F) * Mth.DEG_TO_RAD;
        float pitch = Mth.clamp(data.headPitch(), -40.0F, 40.0F) * Mth.DEG_TO_RAD;
        for (int i = 0; i < NECK_BONES.length; i++) {
            CoreGeoBone bone = getAnimationProcessor().getBone(NECK_BONES[i]);
            if (bone != null) {
                bone.setRotY(bone.getRotY() + yaw * NECK_SHARE[i]);
                bone.setRotX(bone.getRotX() + pitch * NECK_SHARE[i]);
            }
        }
    }
}
